mapper.select:
SELECT p.id AS partner_id, p.code AS partner_code, p.name AS partner_name, m.last_date, m.last_price,
       m.min_date, m.min_price, m.max_date, m.max_price
FROM scm_price_memory m

    JOIN scm_customer p ON p.id = m.partner_id
    JOIN scm_supplier p ON p.id = m.partner_id

WHERE m.kind = #{kind} AND m.material_id = #{q.materialId}
AND p.id = #{q.partnerId}
AND (p.code LIKE CONCAT('%', #{q.keyword}, '%') OR p.name LIKE CONCAT('%', #{q.keyword}, '%'))
AND m.last_date >= #{q.start}
AND m.last_date <= #{q.end}
ORDER BY m.last_date DESC, m.id DESC
LIMIT #{q.limit}
